SELECT state, promo_name, sale_hour, total_sales_net_profit, total_return_net_loss, net_profit_after_returns, RANK() OVER (PARTITION BY promo_name ORDER BY net_profit_after_returns DESC) AS state_rank FROM ( SELECT ca.ca_state AS state, p.p_promo_name AS promo_name, t.t_hour AS sale_hour, SUM(ss.ss_net_profit) AS total_sales_net_profit, SUM(COALESCE(sr.sr_net_loss, 0)) AS total_return_net_loss, SUM(ss.ss_net_profit) - SUM(COALESCE(sr.sr_net_loss, 0)) AS net_profit_after_returns FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN time_dim t ON ss.ss_sold_time_sk = t.t_time_sk JOIN customer_address ca ON ss.ss_addr_sk = ca.ca_address_sk JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk LEFT JOIN store_returns sr ON ss.ss_ticket_number = sr.sr_ticket_number AND ss.ss_item_sk = sr.sr_item_sk WHERE d.d_fy_year = 2002 AND p.p_discount_active = 'Y' GROUP BY ca.ca_state, p.p_promo_name, t.t_hour ) agg ORDER BY net_profit_after_returns DESC LIMIT 100
